from collections import Counter

def is_samepatterns(strs, patterns):
    # Check if the length of the strings and patterns are the same
    if len(strs) != len(patterns):
        return False

    # Create a dictionary to map strings to patterns
    d = {}

    # Iterate over the strings and patterns
    for i in range(len(strs)):
        # If the string is already in the dictionary
        if strs[i] in d:
            # Check if the corresponding pattern matches
            if d[strs[i]] != patterns[i]:
                return False
        else:
            # Map the string to the pattern
            d[strs[i]] = patterns[i]

    # Check if the number of unique patterns matches the number of unique strings
    return len(Counter(patterns)) == len(Counter(strs))

# Test the function with the provided test case
assert is_samepatterns(["red","green","green"], ["a", "b", "b"]) == True
