def check_integer(s):
    # Remove leading and trailing spaces
    s = s.strip()

    # Check if the string is empty after stripping
    if len(s) < 1:
        return None

    else:
        # Check if all characters are digits or if it's a valid negative number
        if s.isnumeric() or (s[0] == '-' and s[1:].isnumeric()):
            return True
        else:
            return False

