def max_product(arr):
    # Initialize the dp array where dp[i] will store the maximum product subsequence ending with arr[i]
    dp = arr[:]

    # Iterate over the array to fill the dp array
    for i in range(1, len(arr)):
        for j in range(i):
            # If arr[i] is greater than arr[j], update dp[i] if the product is greater
            if arr[i] > arr[j] and dp[i] < dp[j] * arr[i]:
                dp[i] = dp[j] * arr[i]

    # Return the maximum value from the dp array, which is the maximum product subsequence
    return max(dp)

# Test the function with the provided test case
assert max_product([3, 100, 4, 5, 150, 6]) == 3000
